if args.command == "export-audit":
    paths = [args.audit_first, args.audit_second, *args.audit_rest]
    try:
        export_audit(paths, args.output)
    except Exception as exc:
        sys.stderr.write(f"ERROR {type(exc).__name__}: {exc}\n")
        return 1
    return 0

